/**
 * app-init.js
 * Mixin untuk inisialisasi aplikasi dan pengecekan setup.
 * Digabungkan ke dalam appData()
 */
window.appInitMixin = function () {
    const getWebAppUrl = async () => {
        try {
            // 1. Cek LocalStorage
            let config = JSON.parse(localStorage.getItem('EzycoreConfig') || '{}');
            if (config.webappUrl) return config.webappUrl;

            // 2. Fallback 1: Cek SSR Hybrid Discovery (Jika elemen sudah ada di DOM)
            console.log('EzyCore Discovery: Memeriksa DOM untuk #ezycore-discovery...');
            const discoveryEl = document.getElementById('ezycore-discovery');
            if (discoveryEl) {
                console.log('EzyCore Discovery: Elemen #ezycore-discovery ditemukan di DOM.');
                if (discoveryEl.dataset.config) {
                    const decoded = JSON.parse(atob(discoveryEl.dataset.config));
                    if (decoded.webappUrl) {
                        console.log('EzyCore Discovery: Berhasil mendekode konfigurasi dari DOM.');
                        localStorage.setItem('EzycoreConfig', JSON.stringify(decoded));
                        return decoded.webappUrl;
                    }
                } else {
                    console.warn('EzyCore Discovery: Elemen ditemukan tetapi atribut data-config kosong.');
                }
            } else {
                console.log('EzyCore Discovery: #ezycore-discovery tidak ada di DOM saat ini (ini normal jika bukan di halaman konfigurasi).');
            }

            // 3. Fallback 2: Remote Discovery via Blogger Feed API
            // Mengambil feed halaman untuk mencari "EzyCore System Configuration"
            console.log('EzyCore Discovery: Mencoba Remote Discovery via Blogger Feed API...');
            const response = await fetch('/feeds/pages/default?alt=json');
            const data = await response.json();
            const entries = data.feed.entry || [];
            console.log(`EzyCore Discovery: Ditemukan ${entries.length} entri halaman di feed.`);

            const configPage = entries.find(e => e.title.$t === 'EzyCore System Configuration');

            if (configPage) {
                console.log('EzyCore Discovery: Halaman "EzyCore System Configuration" ditemukan di Blogger.');
                const content = configPage.content.$t;
                const match = content.match(/data-config="([^"]+)"/);
                if (match && match[1]) {
                    // Decode Base64 yang dihasilkan oleh EzyCoreAi.gs
                    const decoded = JSON.parse(atob(match[1]));
                    if (decoded.webappUrl) {
                        console.log('EzyCore Discovery: Berhasil menemukan dan mendekode konfigurasi dari Remote Page.');
                        localStorage.setItem('EzycoreConfig', JSON.stringify(decoded));
                        return decoded.webappUrl;
                    }
                } else {
                    console.error('EzyCore Discovery: Halaman ditemukan tetapi regex gagal mengekstrak data-config. Konten halaman:', content);
                }
            } else {
                console.error('EzyCore Discovery: Halaman "EzyCore System Configuration" tidak ditemukan di daftar halaman Blogger.');
            }
            return '';
        } catch (e) {
            return '';
        }
    };

    return {
        async fetchJsonp(url, params = {}) {
            const cbName = 'setup_cb_' + Date.now();
            const query = new URLSearchParams(params);
            query.set('callback', cbName);
            const script = document.createElement('script');
            script.src = `${url}${url.includes('?') ? '&' : '?'}${query.toString()}`;
            return new Promise((resolve, reject) => {
                window[cbName] = (res) => {
                    delete window[cbName];
                    script.remove();
                    resolve(res);
                };
                script.onerror = () => {
                    script.remove();
                    reject(new Error('Network Error: Verify WebApp URL is correct and script is deployed as "Anyone".'));
                };
                (document.head || document.documentElement).appendChild(script);
                // Increase timeout to 90s for DB creation
                setTimeout(() => {
                    if (window[cbName]) {
                        delete window[cbName];
                        script.remove();
                        reject(new Error('Connection Timeout: The server took too long to respond.'));
                    }
                }, 90000);
            });
        },

        async checkInitialSetup() {
            // 1. Resolve URL Priority: Blogger Layout > LocalStorage > config.js Gateway
            const hasBloggerUrl = (window.BLOGGER_WEBAPP_URL && window.BLOGGER_WEBAPP_URL.startsWith('http'));
            let webappUrl = hasBloggerUrl ? window.BLOGGER_WEBAPP_URL : await getWebAppUrl();

            // Step 1: Auto-Discovery via Gateway dihapus. 
            // Sistem sekarang sepenuhnya mengandalkan URL dari Blogger Layout atau Konfigurasi Manual.

            // Step 2: Guard jika URL tetap tidak valid
            if (!webappUrl || !webappUrl.startsWith('http')) {
                console.error('CRITICAL: No valid WebApp URL found.');
                this.dbHealthy = false;
                this.dbStatusChecked = true;
                return;
            }

            // Step 3: Ping ke Admin WebApp
            try {
                // console.log('Pinging server at:', webappUrl);
                const data = await this.fetchJsonp(webappUrl, {
                    action: 'get_config',
                    userWebAppUrl: webappUrl, // Laporkan URL terbaru dari widget Blogger
                    email: this.currentUser?.email, // Sertakan konteks user jika ada
                    siteKey: (JSON.parse(localStorage.getItem('EzycoreConfig') || '{}')).siteKey || ''
                });

                // Kirim event agar router global (EzyCoreAi.xml) dapat bereaksi (misal: redirect ke setup)
                window.dispatchEvent(new CustomEvent('ezy-api-ready', {
                    detail: { config: data }
                }));

                // Step 4: Validasi respons
                if ((data.statusNote === 'new_fallback' && !data.dbId) || data.statusNote === 'setup_in_progress') {
                    console.warn('Gateway fallback or setup in progress, skipping forced redirect.');
                    this.dbHealthy = true; // Anggap sehat sementara, tunggu Admin URL valid
                } else {
                    // Sistem dianggap "Healthy" (tidak perlu setup ulang) 
                    // jika server mengonfirmasi adanya Database ID.
                    this.dbHealthy = (data.isSetup === true || (data.dbId && data.dbId.length > 5));
                }

                // Step 5: Simpan konfigurasi jika setup selesai
                if (this.dbHealthy) {
                    const finalUrl = (data.adminUrl && data.adminUrl.startsWith('http')) ? data.adminUrl : webappUrl;
                    localStorage.setItem('EzycoreConfig', JSON.stringify({
                        webappUrl: finalUrl,
                        email: data.email || '',
                        role: 'Admin',
                        dbName: data.dbName || '',
                        sheetId: data.dbId || '',
                        siteKey: data.siteKey || '',
                        blogId: data.blogId || '',
                        pageId: data.pageId || ''
                    }));
                    console.log('Browser synchronized with server configuration.');
                } else {
                    console.warn('EzyCore: Server melaporkan setup belum lengkap.', {
                        isSetup: data.isSetup,
                        statusNote: data.statusNote,
                        dbId: data.dbId,
                        error: data.libraryError
                    });

                    if (data.dbId && !data.isSetup) {
                        console.info('💡 Tip: Database ID ditemukan tetapi tidak dapat diverifikasi. Pastikan file Spreadsheet tidak terhapus dan Anda telah menjalankan "manualAuthorizationHelper" di Editor skrip untuk memberikan izin akses Drive.');
                    }
                }
            } catch (error) {
                console.error('Error fetching setup status:', error);
                this.dbHealthy = false;
            } finally {
                this.dbStatusChecked = true;
            }
        }
    };
};
